import {MAX_FACTORIES,factoryCost,freeFactories,productionBatch,patentRequirements,productName,productionUnlocked,productionRequirements,hireCost,WAGE,PAY_PERIOD,MARKET_PRICES,available,activeWorkers,COUNTRIES,RESOURCES,TECHS,PRODUCTS,PATENTS,newGame,rate,capacity,upgradeCost,unlocked,researchTime,productTime,salePrice,affordable,advance,act,validateSave} from './engine.js';
const $=s=>document.querySelector(s),KEY='arsenal.save.v1';
let productionFilter='all',pinnedResearch=null;
let researchHoverTimer=null,researchHoverSquare=null;
function cancelResearchHover(){clearTimeout(researchHoverTimer);researchHoverTimer=null;researchHoverSquare=null;}
let state=null,view='harvest',selected='fr',screen='title',last=Date.now(),saved=true,toastTimer;
const fmt=n=>Math.floor(n).toLocaleString('fr-FR');
const money=n=>Math.ceil(n).toLocaleString('fr-FR');
const compact=n=>n>=1000?n.toLocaleString('fr-FR',{notation:'compact',maximumFractionDigits:1}):fmt(n);
const dec=n=>n.toLocaleString('fr-FR',{maximumFractionDigits:1});
const clock=n=>`${Math.floor(Math.max(0,n)/60).toString().padStart(2,'0')}:${Math.ceil(Math.max(0,n)%60).toString().padStart(2,'0')}`;
const names={harvest:'Ressources',market:'Marché',production:'Production',research:'Recherche',patents:'Brevets',storage:'Stockage'};
const icons={harvest:'⚒',production:'⚙',research:'⚗',patents:'▤',storage:'▥'};
function notify(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function save(){if(!state)return;try{state.lastSaved=Date.now();localStorage.setItem(KEY,JSON.stringify(state));saved=true;}catch{saved=false;}}
let offlineMessage='';try{const raw=localStorage.getItem(KEY);if(raw){state=validateSave(raw);const elapsed=Math.min(28800,Math.max(0,(Date.now()-state.lastSaved)/1000));advance(state,elapsed);if(elapsed>60)offlineMessage=`Vos ateliers ont travaillé ${Math.floor(elapsed/60)} min pendant votre absence.`;save();}}catch{offlineMessage='La sauvegarde locale est illisible. Vous pouvez importer une copie ou commencer une nouvelle partie.';}
const flag=(id)=>`<span class="flag ${id}" role="img" aria-label="${COUNTRIES[id].name}">${id==='su'?`<svg class="soviet-flag" viewBox="0 0 42 27" aria-hidden="true" focusable="false"><path fill="#a5352b" d="M0 0h42v27H0z"/><g fill="#edc966"><path d="m10 2 1 3h3l-2.5 2 1 3L10 8l-2.5 2 1-3L6 5h3z"/><path d="M12 10c5 1 7 5 5 8-2 4-7 4-10 1l-3 4-2-2 4-4 2 2c3 2 7 0 7-3 0-2-1-4-3-6z"/><path d="m5 11 2-2 6 5-2 2-2-2-2 2-3-3 2-2zm4 4 2-2 7 8-2 2z"/></g></svg>`:''}</span>`;
function art(atlas,x,y,w,h,cls=''){return `<div class="art ${cls}" style="--x:${x};--y:${y};--w:${w};--h:${h};aspect-ratio:${w}/${h}"><img src="assets/${atlas}-atlas.png" alt="" draggable="false" style="width:${1536/w*100}%;left:${-x/w*100}%;top:${-y/h*100}%"></div>`;}
// Both resource atlases use transparent backgrounds and square cells.
function resourceIcon(id){
 const classic=['coal','wood','iron','rubber'].indexOf(id);
 const index=classic>=0?classic:['cotton','copper','gunpowder','shale','oil','manganese','nickel','bauxite'].indexOf(id);
 const columns=classic>=0?2:4;
 const atlas=classic>=0?'classic-resource-icons.png':'resource-icons-atlas.png';
 return `<span class="resource-icon generated-icon" aria-hidden="true"><img src="assets/${atlas}" alt="" draggable="false" style="width:${columns*100}%;height:200%;left:${-(index%columns)*100}%;top:${-Math.floor(index/columns)*100}%"></span>`;
}
function resourceScene(r){return `<div class="art resource-scene" role="img" aria-label="${r.site}"><img src="assets/resources-atlas.png" alt="" draggable="false" style="width:400%;height:300%;left:${-(r.tier%4)*100}%;top:${-Math.floor(r.tier/4)*100}%"></div>`;}
function navArt(id){const index=['harvest','market','production','research','patents','storage'].indexOf(id);return `<span class="nav-art menu-icon" aria-hidden="true"><img src="assets/menu-icons-atlas.png" alt="" draggable="false" style="left:${-(index%3)*100}%;top:${-Math.floor(index/3)*100}%"></span>`;}
function management(){return `<aside class="management"><h2>GESTION</h2><section class="management-card"><h3>RENDEMENT</h3><div class="management-stat"><span>Récolte auto / min</span><strong id="total-rate"></strong></div><div class="management-stat"><span>Salaires / min</span><strong id="total-wages"></strong></div><div class="management-stat"><span>Lignes acquises</span><strong id="total-income"></strong></div><div class="management-stat"><span>Unités livrées</span><strong id="total-sold"></strong></div></section><section class="management-card"><h3>BUREAU D’ÉTUDES</h3>${art('research',1140,214,371,265)}<p id="project-status"></p><div class="meter"><i id="management-research"></i></div><button class="upgrade full" data-view="research">RECHERCHE →</button></section><section class="management-card"><h3>ARCHIVE</h3><img class="archive-illustration" src="assets/archive-library.png" alt="Bibliothèque administrative : dossiers, registres et meubles à archives" draggable="false"><div class="management-stat"><span>Technologies</span><strong>${state.tech.length} / 6</strong></div><div class="management-stat"><span>Brevets</span><strong>${state.patents.length} / ${PRODUCTS.length}</strong></div><button class="secondary full" data-view="storage">VOIR LES STOCKS</button></section><div class="live-dot">USINE OPÉRATIONNELLE</div></aside>`;}
function title(){screen='title';$('#app').innerHTML=`<main class="title-screen"><header class="title-top"><a class="brand" href="#">A<span class="brand-rule"></span></a><span>JEU DE GESTION INDUSTRIELLE · 1914—1945</span><span class="edition">ÉDITION PIXEL / 0.2</span></header><div class="title-body"><div class="eyebrow"><i></i> LES INDUSTRIES DE GUERRE</div><h1>ARSENAL<span>Le pouvoir se construit.</span></h1><p class="intro">Des premières mines aux grandes manufactures.<br>Récoltez, inventez, produisez. Bâtissez votre héritage industriel.</p><div class="choose-label"><span>01</span> CHOISISSEZ VOTRE NATION <small>Une sauvegarde locale par navigateur.</small></div><div class="countries">${Object.entries(COUNTRIES).map(([id,c])=>`<button class="country ${id===selected?'selected':''}" data-country="${id}" aria-pressed="${id===selected}">${flag(id)}<span class="country-name">${c.name}</span><span class="country-motto">${c.motto}</span><strong>${c.bonus}</strong><span class="check">${id===selected?'✓':'○'}</span></button>`).join('')}</div><div class="title-actions"><button class="primary start" data-action="start">FONDER MON INDUSTRIE <span>→</span></button>${state?`<button class="secondary" data-action="continue">Reprendre · ${COUNTRIES[state.country].name} →</button>`:''}</div><p class="title-note">${state?'Une nouvelle partie remplacera votre sauvegarde, après confirmation.':'Une économie à développer. Des inventions à maîtriser. À votre rythme.'}</p></div><footer class="title-footer"><span>SOLO · PROGRESSION HORS LIGNE · SANS COMPTE</span><div><button data-action="import">Importer une partie</button><a href="arsenal-source.zip" download>Code source ↗</a><span>MIT · Open source</span></div></footer></main>`;}
function goal(){if(!Object.values(state.workers).some(crew=>crew.length))return 'Récoltez du charbon, vendez-le au marché, puis engagez votre premier ouvrier pour 27 or.';const next=RESOURCES.find(r=>!state.levels[r.id]);if(next)return `Prochaine exploitation : ${next.name} · ${fmt(next.cost)} or. Gardez une réserve pour les salaires.`;if(!state.lines.some(l=>l.enabled||l.made))return 'Recherchez Machines à vapeur, achetez le brevet Uniforme, puis lancez la confection dans Production.';if(!state.totalSold)return 'Première livraison : vendez votre premier lot dans Production.';if(state.research)return 'Vos ingénieurs travaillent. Rassemblez les ressources nécessaires à la prochaine avancée.';if(!state.tech.length)return 'Rassemblez du charbon et du coton pour rechercher Machines à vapeur.';if(!state.patents.length)return 'Achetez votre première licence de production dans Brevets.';return 'Développez vos ateliers, approvisionnez la recherche et débloquez les blindés.';}
function shell(){screen='game';const c=COUNTRIES[state.country];$('#app').innerHTML=`<div class="game-shell"><header class="topbar"><button class="wordmark" data-action="home">ARSENAL<small>LES INDUSTRIES DE GUERRE</small></button><div class="nation-label">${flag(state.country)}<span>${c.name}<small>${c.bonus}</small></span></div><div class="resource-stocks" role="group" aria-label="Stocks de ressources">${RESOURCES.map(r=>`<div class="resource-stock" title="${r.name}" aria-label="${r.name}" role="group" tabindex="0">${resourceIcon(r.id)}<strong id="header-stock-${r.id}"></strong></div>`).join('')}</div><div class="wallet">${wageIcon()}<div><small>TRÉSORERIE</small><strong id="credits"></strong></div></div><button class="icon-btn" data-action="settings" aria-label="Sauvegarde et paramètres">☰</button></header><aside class="sidebar"><div class="sidebar-label">COMPLEXE INDUSTRIEL</div><nav>${Object.entries(names).map(([id,name])=>`<button data-view="${id}" class="${view===id?'active':''}">${navArt(id)}${name}<b>${id==='research'&&state.research?'•':''}</b></button>`).join('')}</nav>${art('harvest',9,447,250,563,'sidebar-scene')}<div class="sidebar-bottom"><div class="live-dot">USINE OPÉRATIONNELLE</div><p>L’avenir appartient<br>à ceux qui le fabriquent.</p><a href="arsenal-source.zip" download>↗ Code source · MIT</a><button data-action="home">← Écran titre</button></div></aside><main class="workspace"><div class="page-heading"><div><p class="eyebrow">DIRECTION DES OPÉRATIONS / <span>${String(Object.keys(names).indexOf(view)+1).padStart(2,'0')}</span></p><h1>${({harvest:'Récolte des ressources',market:'Marché des matières premières',production:'Ateliers de production',research:'Bureau de recherche',patents:'Bureau des brevets',storage:'Magasins & réserves'})[view]}</h1></div><span class="date-badge">CAMPAGNE INDUSTRIELLE<br><strong>1936</strong></span></div><div class="mission"><span>ORDRE DU JOUR</span><p id="current-goal">${goal()}</p></div><div class="workspace-layout"><div id="content"></div>${management()}</div><footer class="game-footer"><span id="save-status">● Sauvegarde automatique</span><span>ARSENAL / VERSION 0.2 · ÉCONOMIE FICTIVE</span></footer></main></div>`;renderContent();updateNumbers();}
function workerIcon(){return `<span class="worker-icon workforce-icon" aria-hidden="true"><img src="assets/workforce-icons.png" alt="" draggable="false" style="left:0"></span>`;}
function wageIcon(){return `<span class="wage-icon workforce-icon" aria-hidden="true"><img src="assets/workforce-icons.png" alt="" draggable="false" style="left:-100%"></span>`;}
function harvest(){return `<div class="section-intro"><p>Chaque clic rapporte 1 ressource. Engagez des ouvriers pour automatiser la récolte.</p><span>12 RESSOURCES · OUVERTURE PROGRESSIVE</span></div><div class="resource-grid">${RESOURCES.map((r,i)=>{
 const open=unlocked(state,r),ready=available(state,r);
 const reason=ready?'Achetez cette exploitation pour accéder à sa ressource.':`Ouvrez d’abord : ${RESOURCES.find(x=>x.id===r.previous).name}.`;
 return `<article class="resource-card ${!open?'locked':''}"><header><h2>${resourceIcon(r.id)}${r.name}</h2><span class="level" id="level-${r.id}"></span></header>${resourceScene(r)}<div class="resource-info"><span class="serial">EXPLOITATION ${String(i+1).padStart(2,'0')}</span><p>${r.desc}</p>${!open?`<div class="lock-info">${reason}</div><button class="upgrade full" data-action="upgrade" data-id="${r.id}" id="upgrade-${r.id}"></button>`:`<div class="stock-row"><div><small>EN RÉSERVE</small><strong id="stock-${r.id}"></strong></div><span class="rate" id="rate-${r.id}"></span></div><div class="meter"><i id="bar-${r.id}"></i></div><div class="card-actions"><button class="secondary" data-action="harvest" data-id="${r.id}" id="harvest-${r.id}">Récolter +1</button><button class="upgrade" data-action="upgrade" data-id="${r.id}" id="upgrade-${r.id}"></button></div><section class="worker-panel" aria-label="Ouvriers et salaires"><div class="worker-counter" id="crew-${r.id}" role="group" aria-label="Ouvriers engagés">${workerIcon()}<strong id="workers-${r.id}">0</strong><span class="worker-status" id="worker-status-${r.id}" role="img"></span></div><div class="worker-controls"><button class="secondary" data-action="dismiss" data-id="${r.id}" id="dismiss-${r.id}" aria-label="Libérer un ouvrier — ${r.name}" title="Libérer un ouvrier ; le salaire déjà payé n’est pas remboursé">−</button><button class="upgrade" data-action="hire" data-id="${r.id}" id="hire-${r.id}" aria-label="Engager un ouvrier — ${r.name}, ${hireCost(state,r)+WAGE} or" title="Embauche : ${hireCost(state,r)} or + ${WAGE} or pour la première minute ; embauche ×1,3 par ouvrier supplémentaire">+</button></div><div class="worker-wages" id="wages-${r.id}" role="group" title="${WAGE} or par ouvrier et par minute, payés d’avance, même hors ligne ou si le stock est plein. Sans or, les ouvriers se mettent en pause.">${wageIcon()}<strong id="payroll-${r.id}">0</strong><small>/ min</small></div></section>`}</div></article>`;
 }).join('')}</div>`;}
function market(){return `<div class="section-intro"><p>Vendez vos matières premières pour financer vos ouvriers et de nouvelles exploitations.</p><span>PRIX FIXES · PAIEMENT IMMÉDIAT</span></div><div class="market-grid">${RESOURCES.map(r=>`<article class="storage-panel market-card"><h2 class="resource-name">${resourceIcon(r.id)}${r.name}</h2><p class="market-price">${money(MARKET_PRICES[r.id])} or <small>/ unité</small></p><p>En réserve : <strong id="stock-${r.id}"></strong></p><div class="market-actions"><button class="secondary" data-action="sell-resource" data-id="${r.id}" id="sell-resource-${r.id}">Vendre 1 · ${money(MARKET_PRICES[r.id])} or</button><button class="secondary" data-action="sell-ten" data-id="${r.id}" id="sell-ten-${r.id}">Vendre 10 · ${money(MARKET_PRICES[r.id]*10)} or</button><button class="upgrade" data-action="sell-all" data-id="${r.id}" id="sell-all-${r.id}"></button></div></article>`).join('')}</div>`;}
function vehicle(id){const p=PRODUCTS.find(p=>p.id===id);return `<div class="production-sprite" role="img" aria-label="${productName(state,p)}, vue de côté sur une table à dessin industrielle"><img src="assets/production-${state.country}.png" alt="" draggable="false" style="left:${-(p.tier%5)*100}%;top:${-Math.floor(p.tier/5)*100}%"></div>`;}
function factoryIcon(){return '<img class="factory-icon" src="assets/factory-icon.png" alt="" aria-hidden="true" draggable="false">';}
function production(){
 const groups=['all',...new Set(PRODUCTS.map(p=>p.kind))];
 const selected=PRODUCTS.filter(p=>productionFilter==='all'||p.kind===productionFilter);
 return `<div class="section-intro"><p>Recherchez la technologie, achetez le brevet, puis affectez vos usines. Chaque usine produit une unité par cycle ; les matières sont consommées pour chaque unité.</p><span>${PRODUCTS.filter(p=>productionUnlocked(state,p)).length} / ${PRODUCTS.length} ATELIERS ACCESSIBLES</span></div><section class="factory-pool">${factoryIcon()}<div><strong>PARC INDUSTRIEL</strong><p id="factory-summary"></p><small>Prix ×1,3 tous les 5 achats · base 1 000 or · les usines en cours se libèrent en fin de cycle</small></div><button class="upgrade" data-action="buy-factory" id="buy-factory"></button></section><nav class="production-filters" aria-label="Catégories de production">${groups.map(group=>`<button class="secondary ${productionFilter===group?'selected':''}" data-production-filter="${group}" aria-pressed="${productionFilter===group}">${group==='all'?'Tout':group}</button>`).join('')}</nav><div class="production-list">${selected.map(p=>{
 const l=state.lines.find(l=>l.id===p.id),requirements=productionRequirements(state,p),lock=requirements.length>0,number=String(p.tier+1).padStart(2,'0');
 return `<article class="production-card ${lock?'production-locked':''}"><div class="product-art"><span class="serial">ATELIER ${number} / ${p.kind}</span>${vehicle(p.id)}<span class="blueprint-label">PLAN D’ENSEMBLE · ${COUNTRIES[state.country].icon} / ${number}</span></div><div class="product-details"><div class="product-heading"><div><p class="product-category">${number} · ${p.name}</p><h2>${productName(state,p)}</h2></div><span id="status-${p.id}" class="status"></span></div><div class="recipe" aria-label="Matières par unité">${Object.entries(p.recipe).map(([id,n])=>`<span title="${RESOURCES.find(r=>r.id===id).name}">${resourceIcon(id)}<b>${fmt(n)}</b><small>${RESOURCES.find(r=>r.id===id).name}</small></span>`).join('')}</div>${lock?`<div class="production-requirements"><strong>À DÉBLOQUER</strong><ul>${requirements.map(reason=>`<li>${reason}</li>`).join('')}</ul>${p.unlock&&!state.tech.includes(p.unlock)?'<button class="secondary" data-view="research">Ouvrir la recherche →</button>':''}${!state.patents.includes(p.id)?'<button class="upgrade" data-view="patents">Acheter le brevet →</button>':''}</div>`:''}<div class="factory-allocation">${factoryIcon()}<strong id="factories-${p.id}"></strong><button class="secondary" data-action="release-factory" data-id="${p.id}" id="release-factory-${p.id}" aria-label="Retirer une usine — ${p.name}">−</button><button class="upgrade" data-action="assign-factory" data-id="${p.id}" id="assign-factory-${p.id}" aria-label="Affecter une usine — ${p.name}">+</button><small id="batch-${p.id}"></small></div><div class="production-stats"><span>${dec(productTime(state,p))} s / cycle</span><span>${money(salePrice(state,p))} or / unité</span><span id="made-${p.id}"></span></div><div class="meter"><i id="progress-${p.id}"></i></div><div class="card-actions"><button class="secondary" data-action="toggle" data-id="${p.id}" id="toggle-${p.id}"></button><button class="upgrade" data-action="sell" data-id="${p.id}" id="sell-${p.id}"></button></div></div></article>`;
 }).join('')}</div>`;
}
const researchPositions={steam:[2,1],alloys:[1,2],assembly:[2,2],chemistry:[3,2],series:[1,3],logistics:[3,3]};
function researchIcon(id){const drawings={
 steam:'<path d="M7 23h18v-9H7zM10 14V7h5v7m10 3h4v6h-4M5 27h25M18 10V5h5v5"/><path d="M10 19h4m4 0h4"/>',
 assembly:'<path d="M4 23h24v6H4zM7 23V13h7v10m5 0V13h7v10M4 7h24M10 7v6m12-6v6"/><path d="M8 26h2m5 0h2m5 0h2"/>',
 alloys:'<path d="m5 24 5-8h12l5 8v4H5zM8 12l4-7h8l4 7zM10 16l5 8m7-8-5 8M5 24h22"/>',
 chemistry:'<path d="M11 4h10m-8 0v10L5 26v3h22v-3l-8-12V4M9 21h14"/><path d="M12 25h3m4-8h2"/>',
 series:'<path d="M3 5h10v9H3zM19 5h10v9H19zM3 20h10v9H3zM19 20h10v9H19zM13 9h6m5 5v6M13 25h6"/>',
 logistics:'<path d="M3 10h16v14H3zM19 15h6l4 6v3H19M23 15v6h6"/><path d="M6 24v5h5v-5m11 0v5h5v-5M6 6h10"/>'
};return `<svg viewBox="0 0 32 34" aria-hidden="true" shape-rendering="crispEdges" fill="none" stroke="currentColor" stroke-width="2">${drawings[id]}</svg>`;}
function research(){return `<div class="section-intro"><p>Survolez le carré pendant 1 seconde pour consulter son dossier. Cliquez pour le garder ouvert.</p><span>UN PROJET À LA FOIS</span></div><div class="research-tree" aria-label="Arbre des recherches"><svg class="research-links" viewBox="0 0 300 450" preserveAspectRatio="none" aria-hidden="true">${TECHS.flatMap(t=>t.requires.map(id=>{const [x,y]=researchPositions[id],[tx,ty]=researchPositions[t.id];return `<path class="${state.tech.includes(id)?'fulfilled':''}" d="M${x*100-50} ${y*150-75} V${y*150} H${tx*100-50} V${ty*150-75}"/>`;})).join('')}</svg>${TECHS.map((t,i)=>{const done=state.tech.includes(t.id),running=state.research?.id===t.id,ready=t.requires.every(k=>state.tech.includes(k)),[col,row]=researchPositions[t.id],status=done?'VALIDÉ':running?'EN COURS':ready?'ACCESSIBLE':'VERROUILLÉ';return `<div class="research-node ${done?'completed':running?'running':ready?'available':'locked'}" style="grid-column:${col};grid-row:${row}" data-pinned="${pinnedResearch===t.id}"><button class="research-square" data-research-node="${t.id}" aria-label="${t.name} · ${status}" aria-expanded="${pinnedResearch===t.id}" aria-controls="research-detail-${t.id}">${researchIcon(t.id)}<span class="research-node-mark" aria-hidden="true">${done?'✓':running?'◷':ready?'+':'×'}</span></button><span class="research-node-name">${t.name}</span><span class="research-node-state">${status}</span><section class="research-detail" id="research-detail-${t.id}" aria-label="${t.name}"><button class="research-detail-close" data-research-close="${t.id}" aria-label="Fermer le dossier">×</button><div class="resource-info"><span class="serial">DOSSIER R–0${i+1} / ${done?'VALIDÉ':running?'EN COURS':'RECHERCHE'}</span><h2>${t.name}</h2><p><strong>Effets :</strong> ${t.desc}</p><p><strong>Brevets :</strong> ${PRODUCTS.filter(p=>p.unlock===t.id).map(p=>p.name).join(', ')}.</p><div class="tech-requirements"><strong>Prérequis :</strong> ${t.requires.length?t.requires.map(k=>TECHS.find(x=>x.id===k).name).join(', '):'Aucun'}</div>${!done&&!running?`<div class="research-costs" aria-label="Ressources nécessaires"><strong class="research-cost-heading">Ressources nécessaires :</strong>${Object.entries(t.cost).map(([id,n])=>`<div class="research-cost">${resourceIcon(id)}<span>${RESOURCES.find(r=>r.id===id).name}</span><strong id="research-cost-${t.id}-${id}"></strong></div>`).join('')}</div>`:''}${done?'<div class="done-label">✓ Technologie maîtrisée</div>':running?`<div class="meter"><i id="research-bar"></i></div><div class="research-time" id="research-time"></div>`:`<button class="upgrade full" data-action="research" data-id="${t.id}" id="research-${t.id}" ${!ready?'disabled':''}>Lancer la recherche <small>${clock(researchTime(state,t))}</small></button>`}</div></section></div>`;}).join('')}</div><div class="research-legend"><span>□ Verrouillé</span><span>＋ Accessible</span><span>◷ En cours</span><span>✓ Validé</span></div>`;}
function patents(){return `<div class="section-intro"><p>Recherche terminée → achat du brevet → ligne de production. Fabriquez un exemplaire de chaque équipement pour accéder au suivant. Chaque licence s’achète une seule fois.</p><span>${state.patents.length} / ${PRODUCTS.length} LICENCES ACQUISES</span></div><div class="production-list patent-catalog">${PATENTS.map(p=>{const owns=state.patents.includes(p.id),requirements=patentRequirements(state,p);return `<article class="production-card ${!owns&&requirements.length?'production-locked':''}"><div class="product-art"><span class="serial">BREVET ${String(p.tier+1).padStart(2,'0')} / ${p.kind}</span>${vehicle(p.id)}<span class="blueprint-label">DOSSIER D’EXPLOITATION · ${COUNTRIES[state.country].icon}</span></div><div class="product-details"><div class="product-heading"><div><p class="product-category">${p.name}</p><h2>${productName(state,p)}</h2></div><span class="status">${owns?'ACQUIS':requirements.length?'VERROUILLÉ':'DISPONIBLE'}</span></div><p>Recherche : ${TECHS.find(t=>t.id===p.unlock).name} · ${state.tech.includes(p.unlock)?'validée':'requise'}</p><p>Autorise la ligne de production ${p.name}.</p>${!owns&&requirements.length?`<div class="production-requirements"><ul>${requirements.map(r=>`<li>${r}</li>`).join('')}</ul></div>`:''}<div class="production-stats"><span>${wageIcon()} ${money(p.cost)} or · achat unique</span></div><div class="card-actions">${owns?'<button class="upgrade" data-view="production">Ouvrir la production →</button>':`<button class="upgrade" data-action="patent" data-id="${p.id}" id="patent-${p.id}">Acheter le brevet · ${money(p.cost)} or</button>${!state.tech.includes(p.unlock)?'<button class="secondary" data-view="research">Recherche →</button>':requirements.length?'<button class="secondary" data-view="production">Production précédente →</button>':''}`}</div></div></article>`;}).join('')}</div>`;}
function storage(){return `<div class="section-intro"><p>Vos matières premières et vos équipements disponibles.</p><span>CAPACITÉ ADAPTÉE À CHAQUE EXPLOITATION</span></div><section class="storage-panel"><h2>Registre des matières premières</h2>${RESOURCES.map(r=>`<div class="inventory-row"><span class="resource-name">${resourceIcon(r.id)}${r.name}</span><div class="meter"><i id="bar-${r.id}"></i></div><strong id="stock-${r.id}"></strong><small id="rate-${r.id}"></small></div>`).join('')}</section><section class="storage-panel"><h2>Équipements prêts à livrer</h2>${PRODUCTS.map((p,i)=>`<div class="inventory-row"><span>${productName(state,p)}</span><strong id="warehouse-${p.id}"></strong><button class="upgrade" data-action="sell" data-id="${p.id}" id="sell-${p.id}"></button></div>`).join('')}</section>`;}
function renderContent(){cancelResearchHover();$('#content').innerHTML=({harvest,market,production,research,patents,storage})[view]();}
function text(id,value){const el=document.getElementById(id);if(el)el.textContent=value;}
function width(id,v){const el=document.getElementById(id);if(el)el.style.width=Math.min(100,Math.max(0,v))+'%';}
function disable(id,value){const el=document.getElementById(id);if(el)el.disabled=value;}
function updateNumbers(){if(screen!=='game')return;text('credits',money(state.credits)+' or');text('current-goal',goal());text('total-wages',fmt(Object.values(state.workers).reduce((n,crew)=>n+crew.length*WAGE,0))+' or');text('total-rate','+ '+dec(RESOURCES.reduce((sum,r)=>sum+rate(state,r)*60,0)));text('total-income',state.patents.length+' / '+PRODUCTS.length);text('total-sold',fmt(state.totalSold));text('project-status',state.research?TECHS.find(t=>t.id===state.research.id).name+' · '+clock(state.research.remaining):'Ingénieurs disponibles');width('management-research',state.research?100*(1-state.research.remaining/researchTime(state,TECHS.find(t=>t.id===state.research.id))):0);text('save-status',saved?'● Sauvegarde automatique':'⚠ Sauvegarde indisponible · exportez votre partie');for(const r of RESOURCES){text('stock-'+r.id,fmt(state.resources[r.id]));const stockEl=document.getElementById('stock-'+r.id);if(stockEl)stockEl.title=`Capacité : ${fmt(capacity(state,r))}`;text('header-stock-'+r.id,compact(state.resources[r.id]));const headerStock=document.getElementById('header-stock-'+r.id);if(headerStock){headerStock.setAttribute('aria-label',fmt(state.resources[r.id]));headerStock.parentElement.title=`${r.name} : ${fmt(state.resources[r.id])}`;}text('rate-'+r.id,`+ ${dec(rate(state,r)*60)} / min`);text('level-'+r.id,state.levels[r.id]?`NIV. ${state.levels[r.id]}`:'À OUVRIR');text('upgrade-'+r.id,`${state.levels[r.id]?'Améliorer':'Ouvrir'} · ${fmt(upgradeCost(state,r))} ◉`);disable('upgrade-'+r.id,!available(state,r)||state.levels[r.id]>=100||state.credits<upgradeCost(state,r));width('bar-'+r.id,state.resources[r.id]/capacity(state,r)*100);
 const crew=state.workers[r.id],active=activeWorkers(state,r),quantity=Math.floor(state.resources[r.id]);
 text('workers-'+r.id,crew.length);
 text('payroll-'+r.id,crew.length*WAGE);
 const crewStatus=!crew.length?'Aucun ouvrier':active<crew.length?`${active} au travail, ${crew.length-active} en pause : salaire manquant`:`${active} au travail · prochain salaire dans ${Math.ceil(Math.min(...crew))} s`;
 const statusEl=document.getElementById('worker-status-'+r.id);
 if(statusEl){statusEl.textContent=active<crew.length?'Ⅱ':'●';statusEl.dataset.state=!crew.length?'empty':active<crew.length?'paused':'active';statusEl.title=crewStatus;statusEl.setAttribute('aria-label',crewStatus);}
 const crewEl=document.getElementById('crew-'+r.id);if(crewEl){crewEl.title=crewStatus;crewEl.setAttribute('aria-label',`${crew.length} ouvrier(s) · ${crewStatus}`);}
 const wagesEl=document.getElementById('wages-'+r.id);if(wagesEl)wagesEl.setAttribute('aria-label',`Salaires : ${crew.length*WAGE} or par minute`);
 disable('harvest-'+r.id,state.resources[r.id]>=capacity(state,r));
 disable('hire-'+r.id,state.credits<hireCost(state,r)+WAGE||crew.length>=100);
 disable('dismiss-'+r.id,!crew.length);
 disable('sell-resource-'+r.id,quantity<1);disable('sell-ten-'+r.id,quantity<10);disable('sell-all-'+r.id,quantity<1);
 text('sell-all-'+r.id,`Tout vendre (${fmt(quantity)}) · ${money(quantity*MARKET_PRICES[r.id])} or`);
}
 text('factory-summary',state.factories+' usines · '+freeFactories(state)+' disponibles');text('buy-factory',state.factories>=MAX_FACTORIES?'Limite atteinte':'Acheter · '+money(factoryCost(state))+' or');disable('buy-factory',state.factories>=MAX_FACTORIES||state.credits<factoryCost(state));for(const p of PRODUCTS){const l=state.lines.find(l=>l.id===p.id);text('factories-'+p.id,l.factories);text('batch-'+p.id,l.remaining>0?l.batch+' en cours · '+l.factories+' usines au prochain cycle':l.factories+' unités max / cycle · '+productionBatch(state,p,l)+' possibles');disable('assign-factory-'+p.id,(freeFactories(state)<1&&l.factories>=l.batch)||!state.patents.includes(p.id));disable('release-factory-'+p.id,!l.factories);text('status-'+p.id,!l.factories&&!l.batch?'AUCUNE USINE':l.enabled?(l.remaining>0?'EN PRODUCTION':l.stock>=9999?'STOCK PLEIN':!productionUnlocked(state,p)?'PRÉREQUIS MANQUANTS':affordable(state,p.recipe)?'DÉMARRAGE':'MATIÈRES MANQUANTES'):productionUnlocked(state,p)||l.remaining>0?'À L’ARRÊT':'VERROUILLÉ');disable('toggle-'+p.id,!l.enabled&&((!l.factories&&!l.batch)||(l.remaining<=0&&!productionUnlocked(state,p))));text('toggle-'+p.id,l.enabled?'Ⅱ Suspendre':'▶ Lancer la production');text('sell-'+p.id,`Vendre ${l.stock} · ${fmt(l.stock*salePrice(state,p))} ◉`);disable('sell-'+p.id,!l.stock);text('made-'+p.id,`${l.made} unités fabriquées`);text('warehouse-'+p.id,`${l.stock} en stock`);width('progress-'+p.id,l.remaining>0?100*(1-l.remaining/productTime(state,p)):0);}
 for(const t of TECHS){disable('research-'+t.id,!!state.research||state.tech.includes(t.id)||!affordable(state,t.cost)||!t.requires.every(k=>state.tech.includes(k)));for(const [id,n] of Object.entries(t.cost)){text('research-cost-'+t.id+'-'+id,fmt(state.resources[id])+' / '+fmt(n));const el=document.getElementById('research-cost-'+t.id+'-'+id);if(el)el.setAttribute('data-missing',String(state.resources[id]<n));}}
 if(state.research){const t=TECHS.find(t=>t.id===state.research.id);width('research-bar',100*(1-state.research.remaining/researchTime(state,t)));text('research-time',`${clock(state.research.remaining)} · Recherche en cours`);}
 for(const p of PATENTS)disable('patent-'+p.id,state.patents.includes(p.id)||patentRequirements(state,p).length>0||state.credits<p.cost);
}
function settings(){const d=document.createElement('dialog');d.innerHTML=`<form method="dialog"><div class="modal-header"><h2>Archives de l’industrie</h2><button class="icon-btn" aria-label="Fermer">×</button></div><p>Votre partie est sauvegardée dans ce navigateur. Exportez-la pour changer d’appareil ou conserver une copie.</p><div class="modal-actions"><button type="button" class="primary" data-action="export">Exporter la sauvegarde</button><button type="button" class="secondary" data-action="import">Importer une sauvegarde</button><a class="secondary" href="arsenal-source.zip" download>Télécharger le code source ↗</a></div><p class="small">Progression hors ligne limitée à 8 heures. La production consomme les ressources ; vendez vos lots pour gagner des or. Les ouvriers sont payés d’avance chaque minute, y compris hors ligne ; sans or ils se mettent en pause. Les recherches consomment des ressources ; acheter un brevet en or autorise une ligne de production.</p><button class="secondary full">Retour à l’usine</button></form>`;document.body.append(d);d.addEventListener('close',()=>d.remove());d.showModal();}
function download(){save();const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`arsenal-${state.country}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Sauvegarde exportée.');}
function importSave(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const file=input.files[0];if(!file||file.size>100000)throw Error();const next=validateSave(await file.text());if(state&&!confirm('Remplacer votre partie actuelle par cette sauvegarde ?'))return;state=next;advance(state,Math.max(0,(Date.now()-state.lastSaved)/1000));save();last=Date.now();document.querySelector('dialog')?.close();shell();notify('Sauvegarde restaurée.');}catch{notify('Fichier invalide : choisissez une sauvegarde Arsenal au format JSON.');}};input.click();}
// Only the square starts the delay. Once open, the dossier remains reachable.
document.addEventListener('pointerover',e=>{
 const square=e.target.closest('.research-square');
 if(!square||e.pointerType==='touch'||square.contains(e.relatedTarget))return;
 cancelResearchHover();researchHoverSquare=square;
 researchHoverTimer=setTimeout(()=>{
  if(researchHoverSquare!==square||!square.isConnected)return;
  square.closest('.research-node').setAttribute('data-preview','true');
  square.setAttribute('aria-expanded','true');
  researchHoverTimer=null;
 },1000);
});
document.addEventListener('pointerout',e=>{
 const square=e.target.closest('.research-square');
 if(square&&!square.contains(e.relatedTarget)&&researchHoverSquare===square)cancelResearchHover();
 const node=e.target.closest('.research-node');
 if(node&&!node.contains(e.relatedTarget)){
  node.removeAttribute('data-preview');
  node.querySelector('.research-square').setAttribute('aria-expanded',node.getAttribute('data-pinned')==='true'?'true':'false');
 }
});
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.researchNode){pinnedResearch=pinnedResearch===b.dataset.researchNode?null:b.dataset.researchNode;renderContent();updateNumbers();return;}if(b.dataset.researchClose){pinnedResearch=null;renderContent();updateNumbers();return;}if(b.dataset.productionFilter){productionFilter=b.dataset.productionFilter;renderContent();updateNumbers();return;}if(b.dataset.country){selected=b.dataset.country;title();return;}if(b.dataset.view){view=b.dataset.view;shell();return;}const a=b.dataset.action;if(!a)return;if(a==='start'){if(state&&!confirm('Créer une nouvelle industrie et remplacer la sauvegarde actuelle ? Pensez à l’exporter avant.'))return;state=newGame(selected);view='harvest';last=Date.now();save();shell();return;}if(a==='continue'){last=Date.now();shell();if(offlineMessage){notify(offlineMessage);offlineMessage='';}return;}if(a==='home'){save();title();return;}if(a==='settings'){settings();return;}if(a==='export'){download();return;}if(a==='import'){importSave();return;}if(state&&act(state,a,b.dataset.id)){save();if(['harvest','sell-resource','sell-ten','sell-all'].includes(a)){updateNumbers();return;}shell();if(a==='patent')notify('Brevet acquis. Votre ligne de production est autorisée.');}else notify('Conditions ou ressources insuffisantes.');});
setInterval(()=>{const now=Date.now();if(state){const before=state.tech.length,completed=state.lines.filter(l=>l.made>0).length;advance(state,(now-last)/1000);if(state.tech.length!==before){if(screen==='game')shell();notify('Recherche terminée : '+TECHS.find(t=>t.id===state.tech.at(-1)).name);}else if(screen==='game'&&['production','patents'].includes(view)&&completed!==state.lines.filter(l=>l.made>0).length){shell();}updateNumbers();}last=now;},250);
setInterval(save,5000);document.addEventListener('visibilitychange',()=>{if(document.hidden)save();});window.addEventListener('pagehide',save);title();
